  },
  "risks": [
    {
      "code": "LABEL_ERROR",
      "text": "DRIVE PPP is depressed and PNR PPP may be inflated by uncorrected foul endings; any observed positive sequential premium could be a pure labeling artefact."
    },
    {
      "code": "CONFOUNDING",
      "text": "Game state (score, period, clock, opponent defensive rating) jointly influences whether a DRIVE is attempted and the success of a subsequent PNR, biasing naïve comparisons."
    },
    {
      "code": "EXPOSURE_SPARSITY",
      "text": "Aggregate sample may still be adequate, but when conditioning on team, season, and game context the effective number of DRIVE‑then‑PNR sequences could fall below the level needed for precise estimation."
    },
    {
      "code": "MULTIPLE_TESTING",
      "text": "If the analysis is later split by player or team, corrections will be required; the blanket claim 'any teammate' invites a multiple‑comparison problem."
    },
    {
      "code": "DRIFT_NONSTATIONARITY",
      "text": "Play‑type frequencies and foul rates may shift across seasons in ways that affect the test statistic."
    }
  ],
  "predicted_outcome": {
    "supported": 0.1,
    "rejected": 0.2,
    "untestable": 0.3,
    "artifact": 0.3,
    "uncertain": 0.1
  },
  "decision": "do_not_proceed",
  "design": {
    "estimand": "The average causal effect on PNR PPP of the immediately preceding offensive possession being a teammate DRIVE (as labelled in the NBA play‑by‑play), relative to it being any other play type or no labelled play, under a conditional independence assumption given observables.",
    "unit": "One offensive possession that is labelled as a pick‑and‑roll.",
    "sample": "All PNR possessions in the 2022‑23 through 2025‑26 regular seasons and playoffs for which the previous team possession can be identified and has a valid play‑type label (excluding possessions ending in technical free throws, end‑of‑quarter heaves, and garbage‑time defined as final 2 minutes with score differential > 12).",
    "power": "We could have roughly 8 000–12 000 PNR possessions with a preceding label, of which ~6% (≈500–700) are preceded by a teammate DRIVE. This yields 80% power to detect a true effect size of d ≈ 0.12–0.15 (about 0.12–0.15 PPP) in a two‑sided test at α = 0.05, assuming intra‑team clustering. However, this estimate assumes no additional variance from label error or model adjustment; actual power is likely lower.",
    "controls": "Fixed effects for team, season, month, and game location; linear controls for period, seconds remaining, score margin, and opponent defensive rating (lagged 10‑game average). Player random intercepts for both the PNR initiator and the teammate who drove.",
    "falsification": "1) Test whether the DRIVE‑preceding effect also appears when the previous possession is an opponent DRIVE (should be null if causal). 2) Replace DRIVE with a different preceding play type (e.g., POST‑UP, HANDOFF) and check for a similar ‘premium’—if multiple play types show a positive association, it suggests a general sequence‑confounding mechanism rather than a DRIVE‑specific effect.",
    "multiplicity": "The primary test is a single coefficient (prev_teammate_drive) in the full‑sample regression; no subgroup multiplicity adjustments are planned in the confirmatory stage. All secondary splits (by player, team) would be clearly labelled as exploratory and corrected via the Benjamini‑Hochberg procedure.",
    "decision_rule": "Reject the null of zero effect if the coefficient on ‘prev_teammate_drive’ is positive and its two‑sided p‑value (cluster‑robust by team‑season) is less than 0.05. Additionally, require that the point estimate remains ≥ 0.02 PPP when restricting to a manually validated subset of 500 randomly sampled sequences where both the DRIVE and PNR labels have been confirmed by a human auditor.",
    "data_version": "NBA API play‑by‑play and derived possession graph as of 2026‑06‑14, covering the 2022‑23, 2023‑24, 2024‑25, and 2025‑26 (regular and playoffs) seasons, with the initiation‑type mapping of FAM:SF‑CHT‑025 applied to flag suspect labels."
  }
}

